export function describeFunction(name, group, system) {
  const n = name.toLowerCase();
  const sets = [R[group], group === "G_Cranial_Nerves" || group === "G_Peripheral_Nerves" ? R.G_Nerves : null, R[system]];
  for (const set of sets) if (set) for (const [re, text] of set) if (re.test(n)) return text;
  return GROUPS[group]?.[1] || "";
}
